declare(strict_types=1);

namespace WorkerAdmin\Contracts {
    interface TestCenterActionRunner { public function available(string $instancePublicId): array; public function run(string $instancePublicId,string $actionKey,array $input,int $adminId,string $requestKey): array; }
    interface TestCenterRepository {
        public function environmentDiagnostics(): array; public function listInstances(array $filters=[]): array; public function instanceDetail(string $publicId): array;
        public function build(array $scenario,array $params,int $adminId,string $requestKey,?int $sourceInstanceId=null,?int $rebuiltFromInstanceId=null): array;
        public function verify(string $publicId,int $adminId): array; public function cleanupPreview(string $publicId): array;
        public function cleanup(string $publicId,int $adminId,string $expectedPlanDigest): array; public function rebuildSource(string $publicId): array;
    }
    interface SettingsProvider { public function get(string $key,$default=null); public function bool(string $key,bool $default=false): bool; public function int(string $key,int $default=0): int; }
    interface PrivateValueCipher { public function hmac(string $plainText,string $context): string; public function encrypt(string $plainText,string $context): ?string; public function decrypt(string $cipherText,string $context): string; }
}

namespace WorkerAdmin\Infrastructure\Safety { final class TestingEnvironmentPolicy { public static function active(): bool{return true;} } }

namespace WorkerAdmin\Infrastructure\Settings {
    use WorkerAdmin\Contracts\SettingsProvider;
    final class GlobalSettingsProvider implements SettingsProvider {
        public function get(string $key,$default=null){$values=['order.booking_fee_cents'=>1000,'commission.default_rate_bp'=>1000,'commission.minimum_cents'=>500,'order.auto_cancel_days'=>7];return array_key_exists($key,$values)?$values[$key]:$default;}
        public function bool(string $key,bool $default=false): bool{return(bool)$this->get($key,$default);}
        public function int(string $key,int $default=0): int{return(int)$this->get($key,$default);}
    }
}

namespace WorkerAdmin\Infrastructure\Security {
    use WorkerAdmin\Contracts\PrivateValueCipher;
    final class GlobalPrivateValueCipher implements PrivateValueCipher {
        public function hmac(string $plainText,string $context): string{return hash('sha256',$context.'|'.$plainText);}
        public function encrypt(string $plainText,string $context): ?string{return $plainText;}
        public function decrypt(string $cipherText,string $context): string{return $cipherText;}
    }
}

